/* R33: ordinary todos and fixed calendar review are separate user journeys. */
(function(){
  'use strict';
  const t=(zh,en)=>state.language==='en'?en:zh;
  const copy=x=>JSON.parse(JSON.stringify(x));
  const validZone=value=>{try{new Intl.DateTimeFormat('en',{timeZone:value});return !!value;}catch{return false;}};
  const B=(label,a,kind='subtle',attrs='')=>button(label,'ax-'+a,attrs,kind);
  const G=(label,page,kind='text')=>goButton(label,page,kind);
  const names={create:['添加日程','Create event'],update:['更新原日程','Update original event'],cancel:['取消原日程','Cancel original event'],complete:['在 Mote 标记安排完成','Mark arrangement complete in Mote']};
  const phases={proposed:['待你核对','Needs review'],fixed:['等待确认固定内容','Fixed review ready'],approved:['等待目标设备','Waiting for target device'],executing:['正在写入 · 等待回执','Writing · awaiting receipt'],succeeded:['已收到完成回执','Completion receipt received'],uncertain:['保存结果待核实','Result uncertain'],stale:['依据已变更 · 重新核对','Evidence changed · review again'],dismissed:['已忽略','Ignored']};
  function example(id,kind='create'){
    const evidenceId='synthetic-calendar-evidence',quote=t('下周一下午 2 点核对项目资料，持续一小时。','Review project materials next Monday at 2 pm for one hour.');
    if(!state.materials.some(m=>m.id===evidenceId))state.materials.push({id:evidenceId,type:'note',title:t('日程审核示例资料','Calendar review fixture'),body:quote,preview:quote,source:t('合成日程资料','Synthetic calendar material'),sourceId:'calendar-demo',date:'2026-10-23',device:'Central',ownerRelation:'owner',version:1,tags:['合成示例']});
    return{id,kind,status:'proposed',version:1,evidenceVersion:1,evidenceId,evidenceQuote:quote,event:{title:t('项目资料评审','Project material review'),start:'2026-10-26T14:00',end:'2026-10-26T15:00',allDay:false,timezone:'Asia/Shanghai',location:'',notes:''},target:kind==='create'?'':'mac:personal',externalId:kind==='create'?'':'synthetic-original-event-01',originalTitle:t('已有项目评审','Existing project review'),draft:null,review:null,receipt:null};
  }
  function init(){
    state.ax||={settings:{enabled:false,timezone:'Asia/Shanghai',reviewDevices:[]},settingsDraft:null,targets:[],suggestions:state.dataState==='empty'?[]:[example('suggestion-1')],filter:'proposed',todoPage:0,due:'',message:'',open:{},deviceEpoch:1,savedDeviceEpoch:1,analysisFailed:1};
    state.ax.settingsDraft||=copy(state.ax.settings);return state.ax;
  }
  const F=(key,label,value,type='text',hint='',disabled=false)=>'<label class="field"><span>'+label+'</span><input class="field-input" id="ax-'+key+'" data-ax-field="'+key+'" type="'+type+'" value="'+esc(value??'')+'" '+(disabled?'disabled':'')+'>'+(hint?'<small>'+hint+'</small>':'')+'</label>';
  const D=(id,title,body)=>'<details class="focus-disclosure" id="ax-'+id+'" '+(init().open[id]?'open':'')+'><summary>'+title+'</summary><div class="focus-disclosure-body">'+body+'</div></details>';
  const statusText=s=>t(...(phases[s.status]||phases.proposed));
  const found=()=>init().suggestions.find(s=>s.id===state.page.split('/')[2]);
  const message=()=>init().message?'<p class="notice" role="status">'+esc(init().message)+'</p>':'';
  function note(text){init().message=text;persist();render();}
  function targetLabel(id){return init().targets.find(x=>x.id===id)?.label||t('原设备 · 原日历','Original device · original calendar');}
  function tabs(){return'<nav class="ax-tabs" aria-label="'+t('行动类型','Action type')+'">'+G(t('我的待办','Todos'),'todos',state.page==='todos'?'primary':'text')+G(t('日程建议','Calendar suggestions'),'todos/schedule',state.page.startsWith('todos/')?'primary':'text')+'</nav>';}
  function todoPage(){
    const a=init(),all=state.todos.filter(q=>state.todoFilter==='全部'||(state.todoFilter==='已取消'?q.canceled:state.todoFilter==='已完成'?q.done&&!q.canceled:!q.done&&!q.canceled));
    a.todoPage=Math.min(a.todoPage,Math.max(0,Math.ceil(all.length/5)-1));const rows=all.slice(a.todoPage*5,a.todoPage*5+5);
    return '<section class="focus-zone"><h2>'+t('记下一个下一步','Capture the next step')+'</h2><div class="ax-add-todo"><input class="field-input" id="todo-text" aria-label="'+t('待办内容','Todo title')+'" value="'+esc(state.todoDraft)+'" placeholder="'+t('例如：核对新导入的资料','For example: review the imported material')+'">'+B(t('添加待办','Add todo'),'add-todo','primary')+'</div>'+D('todo-due',t('截止日期（选填）','Due date (optional)'),F('due',t('截止日期','Due date'),a.due,'date'))+'</section>'+
      '<section class="focus-zone"><div class="ax-row"><h2>'+t('我的待办','My todos')+'</h2>'+choiceField(t('显示待办','Show todos'),'todo-filter',['未完成','已完成','已取消','全部'],state.todoFilter)+'</div>'+
      (rows.length?rows.map(q=>'<article class="ax-todo"><div><strong data-user-content>'+esc(q.text)+'</strong><p>'+t(q.canceled?'已取消':q.done?'已完成':'未完成',q.canceled?'Cancelled':q.done?'Completed':'Open')+' · '+(q.due?esc(q.due):t('没有截止日期','No due date'))+'</p></div><div class="actions">'+(q.done||q.canceled?B(t('重新打开','Reopen'),'reopen-todo','text','data-id="'+q.id+'"'):B(t('完成','Complete'),'complete-todo','subtle','data-id="'+q.id+'"'))+D('todo-'+q.id,t('更多','More'),(q.source?G(t('查看依据','Open evidence'),'material/'+q.source):'')+(!q.canceled?B(t('取消待办','Cancel todo'),'cancel-todo','text','data-id="'+q.id+'"'):''))+'</div></article>').join(''):'<p class="muted">'+t('当前分类没有待办。','No todos in this category.')+'</p>')+
      (all.length>5?'<div class="ax-row section"><span>'+t('第 ','Page ')+(a.todoPage+1)+' / '+Math.ceil(all.length/5)+'</span><div class="actions">'+B(t('上一页','Previous'),'todo-page','text','data-direction="-1" '+(a.todoPage===0?'disabled':''))+B(t('下一页','Next'),'todo-page','text','data-direction="1" '+((a.todoPage+1)*5>=all.length?'disabled':''))+'</div></div>':'')+'</section><p class="small muted">'+t('待办独立保存。完成待办不会创建日历事件。','Todos are independent. Completing one does not create a calendar event.')+'</p>';
  }
  function evidence(s){return '<blockquote class="ax-evidence"><p>'+esc(s.evidenceQuote)+'</p>'+G(t('核对原始资料','Open original evidence'),'material/'+s.evidenceId)+'<small>'+t('依据版本 ','Evidence version ')+s.evidenceVersion+'</small></blockquote>';}
  function schedule(){
    const a=init(),rows=a.suggestions.filter(s=>a.filter==='all'||a.filter==='proposed'&&['proposed','fixed','stale'].includes(s.status)||a.filter==='active'&&['approved','executing','uncertain'].includes(s.status));
    return '<section class="focus-zone"><div class="ax-row"><div><h2>'+t('待核对的安排','Arrangements to review')+'</h2><p class="small muted">'+t('你先确认，再交给指定设备。','Confirm first, then send to the selected device.')+'</p></div>'+G(t('发现设置','Discovery settings'),'todos/discovery')+'</div><div class="ax-filters">'+[['proposed','待确认','Needs review'],['active','待写入 / 核实','Pending / uncertain'],['all','全部','All']].map(([id,zh,en])=>B(t(zh,en),'filter',a.filter===id?'primary':'text','data-filter="'+id+'"')).join('')+'</div>'+
      (rows.length?rows.map(s=>'<article class="ax-suggestion"><div><span class="small muted">'+t(...names[s.kind])+' · '+statusText(s)+'</span><h3>'+esc((s.review?.event||s.event).title)+'</h3><p>'+esc(s.event.start.replace('T',' '))+' · '+esc(s.event.timezone)+'</p></div>'+G(t(['proposed','fixed','stale'].includes(s.status)?'核对建议':'查看进度',['proposed','fixed','stale'].includes(s.status)?'Review suggestion':'View progress'),'todos/review/'+s.id,['proposed','fixed','stale'].includes(s.status)?'primary':'subtle')+'</article>').join(''):'<div class="ax-empty"><h3>'+t('这里会显示需要你核对的日程','Calendar suggestions appear here')+'</h3><p>'+t('开启发现后，从已上传资料中查找安排建议。每次写入仍需你确认。','Enable discovery to find proposed arrangements in uploaded material. Each write still needs your confirmation.')+'</p>'+G(t('设置发现范围','Set discovery scope'),'todos/discovery','primary')+'</div>')+'</section>'+D('examples',t('预览不同日程操作','Preview calendar operations'),'<p class="small">'+t('以下是合成建议，不会操作真实日历。','These are synthetic suggestions; no real calendar is changed.')+'</p>'+Object.entries(names).map(([kind,l])=>B(t(...l),'example','text','data-kind="'+kind+'"')).join(''));
  }
  function discovery(){
    const a=init(),d=a.settingsDraft,devices=state.devices.filter(q=>!q.revoked),stale=a.deviceEpoch!==a.savedDeviceEpoch;
    return heading(t('日程发现设置','Calendar discovery settings'),t('决定从哪些资料发现建议、由哪些设备审核。','Choose discovery scope and reviewing devices.'),G(t('返回日程建议','Back to suggestions'),'todos/schedule'))+'<article class="reading focus-task">'+message()+'<section class="focus-zone"><h2>'+t('发现范围','Discovery scope')+'</h2><label class="checkrow"><input id="ax-enabled" data-ax-field="enabled" type="checkbox" '+(d.enabled?'checked':'')+'><span>'+t('从已归档资料发现日程建议','Discover calendar suggestions in archived material')+'</span></label>'+F('timezone',t('解释日期的时区','Timezone for interpreting dates'),d.timezone)+
      '<p class="small">'+t('使用行动发现模块配置的模型。只在本机的资料不会因此发送到远程；发现本身不会写入日历。','Uses the configured action-discovery model. Local-only material is not sent remotely by this setting. Discovery never writes a calendar.')+'</p>'+G(t('查看此模块的模型','View module model'),'settings/models')+'</section><section class="focus-zone"><h2>'+t('允许审核的设备','Authorized reviewing devices')+'</h2>'+
      (devices.length?devices.map(q=>'<label class="checkrow"><input type="checkbox" data-ax-device="'+q.id+'" '+(d.reviewDevices.includes(q.id)?'checked':'')+'><span>'+esc(q.name)+'</span></label>').join(''):'<p>'+t('尚未连接设备。','No devices connected.')+'</p>'+G(t('连接采集端','Connect a collector'),'devices'))+
      (stale?'<p class="notice warn" role="alert">'+t('设备授权已变化，请刷新后重新选择。草稿保留。','Device authorization changed. Refresh and reselect; the draft is retained.')+'</p>':'')+'<div class="actions section">'+B(t('保存发现设置','Save discovery settings'),'save-discovery','primary')+B(t('刷新设备','Refresh devices'),'refresh-devices','text')+'</div><p class="small">'+t('已保存：','Saved: ')+t(a.settings.enabled?'已开启':'未开启',a.settings.enabled?'Enabled':'Disabled')+' · '+esc(a.settings.timezone)+'</p></section>'+
      D('analysis-recovery',t('分析进度与恢复','Analysis progress and recovery'),'<p>'+t('分析失败的批次：','Failed analysis batches: ')+a.analysisFailed+'</p>'+B(t('重试分析失败的批次','Retry failed analysis batches'),'retry-analysis')+'<p class="small">'+t('重试不会自动批准或写入建议。','Retry does not approve or write suggestions.')+'</p>')+D('device-change',t('预览授权变化','Preview authorization change'),B(t('模拟审核设备被撤销','Simulate reviewing device revocation'),'revoke-review-device'))+'</article>';
  }
  function devicesPage(){
    const a=init(),devices=state.devices.filter(q=>!q.revoked);
    return heading(t('用于写入的日历','Calendars for writing'),t('读取日历资料和写入日程使用不同授权。','Calendar reading and calendar writing have separate permissions.'),G(t('返回核对','Back to review'),a.returnReview||'todos/schedule'))+'<article class="reading focus-task">'+message()+'<section class="focus-zone"><h2>'+t('连接已有设备上的日历','Connect a calendar on an existing device')+'</h2><p>'+t('请在目标设备允许访问系统日历，再选择已有日历。网页把确认内容交给该设备处理。','Allow system-calendar access on the target device, then choose an existing calendar. The web UI sends the confirmed content to that device.')+'</p>'+
      (devices.length?devices.map(q=>'<div class="ax-row ax-target"><div><strong>'+esc(q.name)+'</strong><p class="small">'+(a.targets.some(c=>c.deviceId===q.id)?t('已收到日历授权回执','Calendar authorization receipt received'):t('等待设备授权','Awaiting device authorization'))+'</p></div>'+B(t('预览此设备授权回执','Preview device authorization receipt'),'connect-calendar','subtle','data-id="'+q.id+'"')+'</div>').join(''):G(t('先连接采集设备','Connect a collector first'),'devices','primary'))+'<p class="small muted">'+t('此 HTML 只模拟授权回执，不会申请系统权限或访问真实日历。','This HTML simulates authorization receipts. It does not request system permission or access a real calendar.')+'</p></section>'+G(t('继续核对','Continue review'),a.returnReview||'todos/schedule','primary')+'</article>';
  }
  function draft(s){s.draft||={...copy(s.event),target:s.target||''};return s.draft;}
  function eventSummary(event){return '<dl class="focus-dl"><div><dt>'+t('标题','Title')+'</dt><dd>'+esc(event.title)+'</dd></div><div><dt>'+t('时间','Time')+'</dt><dd>'+esc(event.start.replace('T',' '))+' → '+esc(event.end.replace('T',' '))+(event.allDay?' · '+t('全天，结束日不包含当天','All-day; end date is exclusive'):'')+'</dd></div><div><dt>'+t('时区','Timezone')+'</dt><dd>'+esc(event.timezone)+'</dd></div><div><dt>'+t('地点与备注','Location and notes')+'</dt><dd class="focus-pre">'+esc([event.location,event.notes].filter(Boolean).join('\n')||t('未填写','Not specified'))+'</dd></div></dl>';}
  function reviewPage(s){
    if(!s)return heading(t('这条建议不存在','Suggestion not found'),' ',G(t('返回建议','Back to suggestions'),'todos/schedule'));
    const actualEvidence=state.materials.find(m=>m.id===s.evidenceId);
    if(actualEvidence?.version>s.evidenceVersion){s.evidenceVersion=actualEvidence.version;s.evidenceQuote=actualEvidence.body;s.version++;if(['proposed','fixed'].includes(s.status))s.status='stale';}
    const a=init(),d=draft(s),fixed=s.review&&s.status==='fixed',active=['approved','executing','uncertain','succeeded','dismissed'].includes(s.status),locked=['cancel','complete'].includes(s.kind),stale=s.status==='stale'||fixed&&s.review.evidenceVersion!==s.evidenceVersion;
    let body='';
    if(active){
      body='<section class="focus-zone"><h2>'+statusText(s)+'</h2>'+eventSummary(s.review?.event||s.event)+'<p>'+targetLabel(s.review?.target||s.target)+'</p>'+(s.externalId?'<p class="small">'+t('原事件：','Original event: ')+esc(s.externalId)+'</p>':'')+
        (s.status==='uncertain'?'<p class="notice warn">'+t('设备可能已经写入。只核实已有事件，不创建第二条。','The device may already have written this event. Verify the existing event without creating another.')+'</p>'+B(t('核实已有事件','Verify existing event'),'verify-event','primary','data-id="'+s.id+'"'):['approved','executing'].includes(s.status)?B(t('打开目标设备同步','Open target device sync'),'open-device','primary','data-id="'+s.id+'"'):'')+
        (s.receipt?'<div class="ax-receipt" role="status"><strong>'+esc(s.receipt.label)+'</strong><p>'+t('操作 ID：','Operation ID: ')+esc(s.receipt.operationId)+'</p><p>'+t('事件 ID：','Event ID: ')+esc(s.receipt.eventId||t('仅 Mote 状态，无日历事件','Mote state only, no calendar event'))+'</p></div>':'')+'</section>'+D('review-evidence',t('核对依据与批准内容','Evidence and approved content'),evidence(s));
      if(s.status!=='dismissed'&&s.status!=='succeeded')body+=D('execution-demo',t('预览设备回执','Preview device receipts'),'<p class="small">'+t('模拟设备状态，不接触真实日历。','Simulated device states; no real calendar is accessed.')+'</p>'+[['executing','设备正在写入','Device is writing'],['uncertain','设备已写入但回执丢失','Written but receipt lost'],['succeeded','收到写入成功回执','Receive success receipt']].map(([value,zh,en])=>B(t(zh,en),'receipt','text','data-id="'+s.id+'" data-state="'+value+'"')).join(''));
    }else if(fixed&&!stale){
      body='<section class="focus-zone"><span class="eyebrow">'+t('固定审核内容','FIXED REVIEW')+'</span><h2>'+t(...names[s.kind])+'</h2>'+eventSummary(s.review.event)+'<p>'+t('目标：','Target: ')+targetLabel(s.review.target)+'</p>'+evidence(s)+'<p class="small">'+t('此确认只批准上方内容、依据版本、设备和日历。修改任何一项都要重新核对。不会邀请参与人。','This approval binds the content, evidence version, device and calendar shown above. Changes require a new review. No participants will be invited.')+'</p><div class="actions section">'+B(t(s.kind==='complete'?'确认在 Mote 标记完成':'确认交给此设备',s.kind==='complete'?'Confirm completion in Mote':'Confirm for this device'),'approve','primary','data-id="'+s.id+'"')+B(t('返回修改','Edit again'),'edit-review','text','data-id="'+s.id+'"')+B(t('忽略建议','Ignore suggestion'),'ignore','text','data-id="'+s.id+'"')+'</div></section>';
    }else{
      body=(stale?'<p class="notice warn" role="alert">'+t('原始依据已经变化。旧确认不可继续；草稿保留，请重新核对。','The evidence changed. The old confirmation cannot continue. Your draft is retained; review it again.')+'</p>':'')+'<section class="focus-zone"><h2>'+t(...names[s.kind])+'</h2>'+(s.kind!=='create'?'<p>'+t('关联原安排：','Original arrangement: ')+esc(s.originalTitle)+' · '+esc(s.externalId)+'</p>':'')+
        F('title',t('标题','Title'),d.title,'text','',locked)+'<label class="checkrow"><input type="checkbox" id="ax-allDay" data-ax-field="allDay" '+(d.allDay?'checked':'')+' '+(locked?'disabled':'')+'><span>'+t('全天','All-day')+'</span></label><div class="ax-grid">'+F('start',t('开始','Start'),d.start,d.allDay?'date':'datetime-local','',locked)+F('end',t('结束','End'),d.end,d.allDay?'date':'datetime-local',d.allDay?t('结束日期不包含当天。','The end date is exclusive.'):'',locked)+'</div>'+F('timezone',t('时区','Timezone'),d.timezone,'text','',locked)+D('event-notes',t('地点与备注','Location and notes'),F('location',t('地点','Location'),d.location,'text','',locked)+'<label class="field"><span>'+t('备注','Notes')+'</span><textarea class="field-input" id="ax-notes" data-ax-field="notes" '+(locked?'disabled':'')+'>'+esc(d.notes)+'</textarea></label>')+'</section>'+
        '<section class="focus-zone"><h2>'+t('核对依据与目标','Check evidence and target')+'</h2>'+evidence(s)+
        (s.kind==='create'?'<label class="field"><span>'+t('已有设备与日历','Existing device and calendar')+'</span><select class="field-input" id="ax-target" data-ax-field="target"><option value="">'+t('选择已授权的日历','Choose an authorized calendar')+'</option>'+a.targets.map(q=>'<option value="'+q.id+'" '+(d.target===q.id?'selected':'')+'>'+esc(q.label)+'</option>').join('')+'</select></label>'+B(t('连接目标设备日历','Connect a target device calendar'),'calendar-target','text','data-id="'+s.id+'"'):'<p>'+t(s.kind==='complete'?'仅在 Mote 标记完成，不写入系统日历。':'只修改或取消原设备、原日历中的这一条事件。',s.kind==='complete'?'Marks completion only in Mote; no system-calendar write.':'Only updates or cancels the original event on its original device and calendar.')+'</p>')+'<div class="actions section">'+B(t('核对固定内容','Prepare fixed review'),'freeze-review','primary','data-id="'+s.id+'"')+B(t('忽略建议','Ignore suggestion'),'ignore','text','data-id="'+s.id+'"')+'</div></section>';
    }
    if(!active)body+=D('stale-demo',t('预览依据变更','Preview an evidence change'),B(t('模拟原始资料出现新版本','Simulate a new evidence version'),'change-evidence','text','data-id="'+s.id+'"'));
    return heading(t('核对日程建议','Review a calendar suggestion'),t('确认要做什么，再交给已有设备。','Review the operation before sending it to an existing device.'),G(t('返回日程建议','Back to suggestions'),'todos/schedule'))+'<article class="reading focus-task">'+message()+body+'</article>';
  }
  todosPage=function(){init();if(state.page==='todos/discovery')return discovery();if(state.page==='todos/devices')return devicesPage();if(state.page.startsWith('todos/review/'))return reviewPage(found());return heading(t('待办与日程','Todos and calendar'),t('记下下一步，核对需要安排的日程。','Track the next step and review proposed arrangements.'),G(t('回到今天','Back to Today'),'today'))+'<article class="reading focus-task">'+tabs()+message()+(state.page==='todos/schedule'?schedule():todoPage())+'</article>';};
  calendarCard=function(){return schedule();};
  function writeReceipt(s,verified=false){s.status='succeeded';s.externalId||='synthetic-event-'+s.id;s.receipt={operationId:s.operationId||'operation-'+s.id,eventId:s.kind==='complete'?'':s.externalId,label:t(s.kind==='complete'?'已在 Mote 中标记完成':s.kind==='cancel'?'已取消原事件':verified?'已核实原事件，未创建重复事件':s.kind==='update'?'已更新原事件':'已写入已有日历 · #Mote',s.kind==='complete'?'Completed in Mote':s.kind==='cancel'?'Original event cancelled':verified?'Existing event verified; no duplicate created':s.kind==='update'?'Original event updated':'Written to existing calendar · #Mote')};}
  function read(e){
    const el=e.target;if(!el.dataset.axField&&!el.dataset.axDevice)return;
    const a=init(),key=el.dataset.axField;if(el.dataset.axDevice){a.settingsDraft.reviewDevices=el.checked?[...new Set([...a.settingsDraft.reviewDevices,el.dataset.axDevice])]:a.settingsDraft.reviewDevices.filter(v=>v!==el.dataset.axDevice);persist();return;}
    if(!key)return;const value=el.type==='checkbox'?el.checked:el.value;
    if(state.page==='todos/discovery')a.settingsDraft[key]=value;else if(key==='due')a.due=value;else{const s=found();if(!s||s.status==='fixed')return;draft(s)[key]=value;if(key==='allDay'){s.draft.start=value?s.draft.start.slice(0,10):s.draft.start.slice(0,10)+'T09:00';s.draft.end=value?s.draft.end.slice(0,10):s.draft.end.slice(0,10)+'T10:00';}}
    persist();if(key==='allDay'&&e.type==='change')render();
  }
  document.addEventListener('input',read);document.addEventListener('change',read);
  document.addEventListener('toggle',e=>{if(e.target.tagName==='DETAILS'&&e.target.id.startsWith('ax-')){init().open[e.target.id.slice(3)]=e.target.open;persist();}},true);
  document.addEventListener('click',e=>{
    const el=e.target.closest('[data-action^="ax-"]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();const action=el.dataset.action.slice(3),a=init(),s=a.suggestions.find(q=>q.id===el.dataset.id);
    a.message='';
    if(action==='add-todo'){if(!state.todoDraft.trim())return note(t('先填写待办内容。','Enter a todo title.'));state.todos.push({id:'todo-'+Date.now(),text:state.todoDraft,done:false,canceled:false,due:a.due});state.todoDraft='';a.due='';state.todoFilter='未完成';a.todoPage=0;return note(t('待办已保存，没有创建日历事件。','Todo saved; no calendar event created.'));}
    if(['complete-todo','cancel-todo','reopen-todo'].includes(action)){const q=state.todos.find(q=>q.id===el.dataset.id);if(q){q.done=action==='complete-todo';q.canceled=action==='cancel-todo';}return note(t('待办状态已保存。','Todo state saved.'));}
    if(action==='todo-page'){a.todoPage+=Number(el.dataset.direction);persist();return render();}
    if(action==='filter'){a.filter=el.dataset.filter;persist();return render();}
    if(action==='example'){const id='suggestion-'+Date.now();a.suggestions.unshift(example(id,el.dataset.kind));persist();return go('todos/review/'+id);}
    if(action==='save-discovery'){if(a.deviceEpoch!==a.savedDeviceEpoch)return note(t('请先刷新设备授权，再保存。','Refresh device authorization before saving.'));if(!validZone(a.settingsDraft.timezone))return note(t('请填写有效时区，例如 Asia/Shanghai。','Enter a valid timezone, such as Asia/Shanghai.'));a.settings=copy(a.settingsDraft);return note(t('发现设置已保存。发现不会自动写入日历。','Discovery settings saved. Discovery does not write calendar events.'));}
    if(action==='refresh-devices'){a.savedDeviceEpoch=a.deviceEpoch;a.settingsDraft.reviewDevices=a.settingsDraft.reviewDevices.filter(id=>state.devices.some(d=>d.id===id&&!d.revoked));return note(t('设备列表已刷新；请核对保留的选择。','Devices refreshed; review the retained selection.'));}
    if(action==='revoke-review-device'){a.deviceEpoch++;const id=a.settingsDraft.reviewDevices[0];if(id){const d=state.devices.find(q=>q.id===id);if(d)d.revoked=true;}return note(t('合成回执：审核设备授权发生变化。','Synthetic receipt: review-device authorization changed.'));}
    if(action==='retry-analysis'){a.analysisFailed=0;return note(t('失败批次已重新排队，尚未生成或批准新的日程。','Failed batches requeued; no new event is generated or approved yet.'));}
    if(action==='calendar-target'){a.returnReview='todos/review/'+s.id;persist();return go('todos/devices');}
    if(action==='connect-calendar'){const d=state.devices.find(q=>q.id===el.dataset.id&&!q.revoked);if(!d)return note(t('此设备已不可用，请刷新设备。','Device unavailable; refresh devices.'));for(const [id,zh,en]of [['personal','个人日历','Personal calendar'],['work','工作日历','Work calendar']]){const key=d.id+':'+id;if(!a.targets.some(q=>q.id===key))a.targets.push({id:key,deviceId:d.id,label:d.name+' · '+t(zh,en),synthetic:true});}return note(t('已收到合成日历授权回执。可返回选择目标。','Synthetic calendar authorization received. Return to choose a target.'));}
    if(!s)return;
    if(action==='freeze-review'){const d=draft(s);if(['create','update'].includes(s.kind)&&(!d.title.trim()||!d.start||!d.end||d.end<=d.start||!validZone(d.timezone)))return note(t('请核对标题、时区及起止时间；结束必须晚于开始。','Check title, timezone and times; end must follow start.'));if(s.kind==='create'&&!a.targets.some(q=>q.id===d.target&&state.devices.some(device=>device.id===q.deviceId&&!device.revoked)))return note(t('请选择已授权的目标设备与已有日历。','Choose an authorized device and existing calendar.'));s.review={event:copy(d),target:s.kind==='create'?d.target:s.target,evidenceVersion:s.evidenceVersion,version:s.version};s.event=copy(d);s.status='fixed';persist();return render();}
    if(action==='edit-review'){s.status='proposed';s.review=null;persist();return render();}
    if(action==='change-evidence'){s.evidenceVersion++;s.version++;s.status='stale';const m=state.materials.find(m=>m.id===s.evidenceId);if(m){m.version=s.evidenceVersion;m.body=s.evidenceQuote+'\n'+t('补充：地点仍需核对。','Update: the location still needs verification.');s.evidenceQuote=m.body;}return note(t('原始依据已更新，请重新核对保留的草稿。','Evidence updated; review the retained draft again.'));}
    if(action==='approve'){if(!s.review||s.review.evidenceVersion!==s.evidenceVersion||s.review.version!==s.version){s.status='stale';return note(t('依据已经变化，不能继续旧确认。','Evidence changed; the previous approval is unavailable.'));}s.operationId||='operation-'+s.id;s.status=s.kind==='complete'?'succeeded':'approved';if(s.kind==='complete')writeReceipt(s);return note(t(s.kind==='complete'?'已在 Mote 中标记完成。':'已确认，等待目标设备处理。',s.kind==='complete'?'Marked complete in Mote.':'Confirmed; waiting for the target device.'));}
    if(action==='ignore'){s.status='dismissed';return note(t('已忽略这条建议，原始资料保留。','Suggestion ignored; original material retained.'));}
    if(action==='open-device'){a.open['execution-demo']=true;return note(t('请在目标设备打开日程建议并同步。下方可预览回执。','Open calendar suggestions on the target device and sync. Preview receipts below.'));}
    if(action==='receipt'){s.status=el.dataset.state;if(s.status==='uncertain')s.externalId||='synthetic-event-'+s.id;if(s.status==='succeeded')writeReceipt(s);persist();return render();}
    if(action==='verify-event'){if(s.status!=='uncertain')return;writeReceipt(s,true);return note(t('已按同一事件和操作 ID 核实，没有新建事件。','Verified the same event and operation IDs without creating an event.'));}
  },true);
})();
